:"never"},"drivetrain_platform":{"kind":"never"},"chain_profile_family":{"kind":"never"},"kit_members":{"kind":"never"},"spec_evidence_source":{"kind":"never"},"included_chainring_count":{"kind":"always"},"crankset_construction":{"kind":"always"},"bottom_bracket_included":{"kind":"always"},"crankset_bottom_bracket_supplied":{"kind":"when","rows":[[{"field":"bottom_bracket_included","operator":"eq","value_type":"boolean","value":true}]]},"chainring_mounting":{"kind":"when","rows":[[{"field":"included_chainring_count","operator":"gt","value_type":"decimal","value":"0"}]]},"crankset_chain_guard_included":{"kind":"never"},"crank_fixing_bolt_included":{"kind":"never"},"crankset_compatibility_claims":{"kind":"never"},"crank_axle_interface_declarations":{"kind":"always"}},"allowed_options":{"pedal_thread":["9/16","1/2","Desconocido / sin confirmar"]},"prerequisites":{"bottom_bracket_required":["spec_evidence_source"],"chainring_teeth_rows":["spec_evidence_source"],"crankset_compatibility_claims":["spec_evidence_source"],"crank_arm_length_mm":["spec_evidence_source"],"pedal_thread":["spec_evidence_source"],"chainring_mount_type":["spec_evidence_source"],"chainline_mm":["spec_evidence_source"],"chainring_mounting":["spec_evidence_source"],"crank_axle_interface_declarations":["spec_evidence_source"]},"helpers":{"chainring_count":"Cantidad antigua sin distinguir contenido y configuración. Se conserva; no se copia al contenido ni acredita capacidad de montaje.","included_chainring_count":"Número de platos o coronas dentadas suministrados con esta variante. Dos coronas integradas en una pieza cuentan como dos platos; no es cantidad de unidades comerciales ni de posiciones simultáneas. Cero requiere exclusión documentada. Sin confirmación queda Sin dato; no se deriva de opciones, fotografías incompletas ni condiciones de pesaje.","chainring_teeth_rows":"Un plato por fila, con su posición y su propio círculo de pernos. Un triple puede llevar dos círculos distintos en el mismo conjunto: el exterior y el medio en uno, el interior en otro.","crankset_construction":"Distingue eje independiente, eje solidario a un brazo, semiejes unidos en el centro y construcción de una pieza. No es el número de platos ni una aprobación de compatibilidad por número de piezas.","spindle_interface":"Qué recibe el eje en este conjunto, o qué eje trae. En una biela de una pieza el eje es la propia biela.","spindle_taper_standard":"Cuál de los dos cuadrados declara el documento. JIS e ISO comparten el ángulo de 2°; el ISO es más largo y termina más fino, así que la misma biela se asienta unos 4,5 mm más afuera sobre un eje JIS. Eso mueve la línea de cadena, y no es una incompatibilidad física universal: la fuente habla de elegir el largo de eje que da la línea buscada. No se deduce de la marca.","chainline_mm":"Línea de cadena que publica el fabricante para este conjunto con su propio eje. Si el eje va aparte, la línea depende del pedalier y del largo de eje elegidos y se declara en cada combinación.","bottom_bracket_required":"Una fila por combinación documentada: caja, pedalier, largo de eje, línea de cadena resultante y su condición. Un mismo conjunto admite varios pedalieres con líneas distintas; una cifra de una fila no vale para las demás ni para otros modelos.","bottom_bracket_included":"Que el conjunto necesite una caja determinada y que el envase traiga el pedalier son dos respuestas distintas.","crankset_bottom_bracket_supplied":"Lo que trae la caja, identificado. Sin pedalier incluido no hay contenido que declarar.","chainring_mounting":"Si los platos se sacan con pernos, si van remachados y no se desmontan, o si el plato va direct mount al brazo. Un conjunto sin platos incluidos no responde esto.","crankset_chain_guard_included":"Contenido del envase, no una compatibilidad.","crank_fixing_bolt_included":"Contenido del envase. Su presencia no dice qué eje recibe.","crankset_compatibility_claims":"Declaraciones documentadas, una por fila, con su alcance y su fuente. El grado lo pone el documento: un fabricante puede declarar la misma pieza, una pieza usable con diferencias, o ninguna equivalencia. La ausencia de una declaración no es una equivalencia, y una marca compartida tampoco.","crank_axle_interface_declarations":"La unión entre biela y eje, descrita una sola vez: si esta pieza ofrece el eje o recibe su asiento, qué sistema es dueño del eje cuando lo recibe, la geometría documentada y la designación exacta de la fuente. Un motor central puede usar distintas interfaces: su función no permite deducir cuadradillo ni estriado, y dos designaciones iguales de texto no son una compatibilidad.","spec_evidence_source":"Fuente de la ficha. Una lista descriptiva de plataformas o de velocidades no aprueba un montaje: lo que autoriza una decisión es la declaración por destino, configuración o pieza, con su documento."},"evidence_requirements":{"chainring_count":"name_reading_hint_only","front_chainring_count":"name_reading_hint_only","chainring_teeth_rows":"package_or_label","chainring_teeth":"name_reading_hint_only","spindle_interface":"oem_or_package","spindle_included":"package_or_label","spindle_taper_standard":"oem_spec","bottom_bracket_required":"oem_spec","bottom_bracket_family":"name_reading_hint_only","crank_arm_length_mm":"oem_or_package","chainline_mm":"oem_spec","pedal_thread":"package_or_label","chainring_mount_type":"oem_or_package","chainring_bcd_mm":"oem_or_package","compatible_rear_speeds":"oem_spec","drivetrain_speeds":"name_reading_hint_only","drivetrain_platform":"oem_spec","chain_profile_family":"name_reading_hint_only","kit_members":"package_or_label","spec_evidence_source":"oem_or_package","included_chainring_count":"package_or_label","crankset_construction":"oem_or_package","bottom_bracket_included":"oem_or_package","crankset_bottom_bracket_supplied":"oem_or_package","chainring_mounting":"oem_or_package","crankset_chain_guard_included":"oem_or_package","crank_fixing_bolt_included":"oem_or_package","cr