nce_source"],"chainring_set_members":["spec_evidence_source"],"chainring_direct_mount_generation":["spec_evidence_source"],"chainring_member_offsets":["spec_evidence_source"],"chainring_member_oem_pairings":["spec_evidence_source"],"chainring_member_compatibility_claims":["spec_evidence_source"]},"helpers":{"chainring_package_kind":"Un plato suelto o un juego de platos en el mismo envase. Un juego doble o triple no es un plato con varias medidas: cada plato tiene sus dientes, su posición y su propio círculo de pernos.","chainring_bolt_pattern_symmetric":"Si los pernos están repartidos en ángulos iguales. Dos platos del mismo diámetro de círculo pueden tener repartos distintos, así que un BCD igual no prueba que el plato calce.","chainring_bcd_mm":"Diámetro del círculo de pernos de este plato. No dice cuántos pernos hay ni cómo están repartidos, y un conjunto puede llevar dos círculos.","chainring_set_member_count":"Se cuenta lo que trae el envase, no los dientes.","chainring_set_members":"Un plato por fila, con su posición, sus dientes y su propio círculo de pernos. Un juego triple documentado lleva dos círculos distintos, así que el juego no responde con una sola medida.","chainring_direct_mount_generation":"Qué asiento direct mount exacto declara el documento, con su generación. Decir «direct mount» no basta: el mismo fabricante publica asientos distintos que no se intercambian.","chainring_offset_declarations":"Un desplazamiento sin decir desde dónde se mide no es una cota. Esto no es la línea de cadena del conjunto armado, que pertenece a la ficha del volante.","chainring_oem_pairing_declarations":"El fabricante publica el plato dentro de una combinación y le da su propia designación y sus propios pernos. Los mismos dientes en otra combinación son otra pieza, así que un número de dientes no identifica el plato.","chainring_compatibility_claims":"Declaraciones documentadas, una por fila, con su alcance y su fuente. El grado lo pone el documento: un fabricante puede declarar la misma pieza, una pieza usable con diferencias, o ninguna equivalencia. La ausencia de una declaración no es una equivalencia, y una marca compartida tampoco.","chainring_member_offsets":"La declaración pertenece a la pieza indicada; no se hereda al resto del envase.","chainring_member_oem_pairings":"La declaración pertenece a la pieza indicada; no se hereda al resto del envase.","chainring_member_compatibility_claims":"La declaración pertenece a la pieza indicada; no se hereda al resto del envase.","spec_evidence_source":"Fuente de la ficha. Una lista descriptiva de plataformas o de velocidades no aprueba un montaje: lo que autoriza una decisión es la declaración por destino, configuración o pieza, con su documento."},"evidence_requirements":{"teeth_count":"oem_or_package","chainring_teeth":"name_reading_hint_only","chainring_mount_type":"oem_or_package","chainring_bolt_count":"name_reading_hint_only","chainring_bcd_mm":"oem_or_package","chainring_bolt_pattern_symmetric":"oem_spec","chainring_offset_mm":"oem_spec","narrow_wide":"oem_or_package","chainring_position":"oem_or_package","compatible_rear_speeds":"oem_spec","drivetrain_speeds":"name_reading_hint_only","chain_width_family":"oem_or_package","drivetrain_platform":"oem_spec","chain_profile_family":"name_reading_hint_only","spec_evidence_source":"oem_or_package","chainring_package_kind":"oem_or_package","chainring_set_member_count":"oem_or_package","chainring_set_members":"oem_or_package","chainring_direct_mount_generation":"oem_or_package","chainring_offset_declarations":"oem_or_package","chainring_oem_pairing_declarations":"oem_or_package","chainring_compatibility_claims":"oem_or_package","chainring_member_offsets":"oem_or_package","chainring_member_oem_pairings":"oem_or_package","chainring_member_compatibility_claims":"oem_or_package"},"row_coherence":{"version":2,"links":[{"id":"chainring_member_offsets_owner","field":"chainring_member_offsets","column":"member_reference","target_field":"chai